package cache

import (
	"context"
	"errors"
	"time"
)

var ErrCacheMiss = errors.New("cache: key not found")

// Client wraps a Redis-like interface for cache operations.
type Client struct {
	store map[string]CacheEntry
}

// NewClient creates a new in-memory cache client (for testing / local dev).
func NewClient() *Client {
	return &Client{store: make(map[string]CacheEntry)}
}

// Get retrieves a value from cache by key.
func (c *Client) Get(ctx context.Context, key string) (string, error) {
	entry, ok := c.store[key]
	if !ok || time.Now().After(entry.ExpiresAt) {
		return "", ErrCacheMiss
	}
	return entry.Value, nil
}

// Set stores a value in cache with TTL.
func (c *Client) Set(ctx context.Context, key string, value string, ttl time.Duration) error {
	c.store[key] = CacheEntry{
		Key:       key,
		Value:     value,
		ExpiresAt: time.Now().Add(ttl),
	}
	return nil
}

// Delete removes a key from cache.
func (c *Client) Delete(ctx context.Context, key string) error {
	delete(c.store, key)
	return nil
}

// DeleteByPattern removes all keys matching a prefix pattern.
func (c *Client) DeleteByPattern(ctx context.Context, pattern string) error {
	for k := range c.store {
		if len(k) >= len(pattern) && k[:len(pattern)] == pattern {
			delete(c.store, k)
		}
	}
	return nil
}

package main

import (
	"log"
	"net/http"

	"github.com/example/order-service/internal/api"
	"github.com/example/order-service/internal/cache"
	"github.com/example/order-service/internal/middleware"
	"github.com/example/order-service/internal/repository"
)

func main() {
	log.Println("Starting order-service...")

	// Initialize cache client
	cacheClient := cache.NewClient()

	// Initialize repositories
	orderRepo := repository.NewOrderRepository(cacheClient)

	// Initialize handlers
	orderHandler := api.NewOrderHandler(cacheClient, orderRepo)

	// Initialize middleware
	cacheMW := middleware.NewCacheMiddleware(cacheClient)

	// Setup routes
	mux := http.NewServeMux()

	mux.HandleFunc("/orders/get", orderHandler.GetOrder)
	mux.HandleFunc("/orders/list", orderHandler.ListOrders)
	mux.HandleFunc("/orders/invalidate", orderHandler.InvalidateOrderCache)
	mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(200)
		w.Write([]byte("ok"))
	})

	log.Println("order-service listening on :8080")
	if err := http.ListenAndServe(":8080", mux); err != nil {
		log.Fatalf("Failed to start server: %v", err)
	}

	// NOTE: cacheMW is initialized but not yet wired into routes.
	// It is used by background jobs for cache warming.
	_ = cacheMW
}

