parser = argparse.ArgumentParser(description="Compare pinned runtime dependencies with the local lock")
parser.add_argument("--project", required=True, type=Path)
parser.add_argument("--lock", required=True, type=Path)
args = parser.parse_args()

with args.project.open("rb") as stream:
    project = tomllib.load(stream)["project"]
with args.lock.open(encoding="utf-8") as stream:
    lock = json.load(stream)

expected = {}
for requirement in project["dependencies"]:
    name, separator, version = requirement.partition("==")
    if not separator or not name or not version:
        raise SystemExit("Runtime dependencies must use exact version pins")
    if name in expected:
        raise SystemExit("Duplicate runtime dependency")
    expected[name] = version

actual = {}
for package in lock["packages"]:
    if package["name"] in actual:
        raise SystemExit("Duplicate locked package")
    actual[package["name"]] = package["version"]

if lock["lock_version"] != 1 or lock["project"] != project["name"]:
    raise SystemExit("Lock header does not match the project")
if actual != expected:
    raise SystemExit("Runtime dependency lock differs from project pins")
print(f"{project['name']}: {len(actual)} pinned runtime dependencies")
